    "<up>": "\x1b[A", "<down>": "\x1b[B", "<right>": "\x1b[C", "<left>": "\x1b[D",
    "<enter>": "\r", "<tab>": "\t", "<stab>": "\x1b[Z", "<esc>": "\x1b",
    "<bs>": "\x7f", "<space>": " ", "<home>": "\x1b[H", "<end>": "\x1b[F",
    "<pgup>": "\x1b[5~", "<pgdn>": "\x1b[6~", "<del>": "\x1b[3~",
    "<ctrl-c>": "\x03", "<ctrl-d>": "\x04",
}

def parse_keys(s):
    out = []
    i = 0
    while i < len(s):
        if s[i] == "<":
            j = s.find(">", i)
            if j != -1:
                tok = s[i:j+1].lower()
                if tok in KEYMAP:
                    out.append(KEYMAP[tok]); i = j+1; continue
                if tok.startswith("<sleep:"):
                    out.append(("sleep", float(tok[7:-1]))); i = j+1; continue
        out.append(s[i]); i += 1
    return out

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--rows", type=int, default=50)
    ap.add_argument("--cols", type=int, default=180)
    ap.add_argument("--keys", default="")
    ap.add_argument("--delay", type=float, default=0.3)
    ap.add_argument("--initial-wait", type=float, default=1.0)
    ap.add_argument("--exit-wait", type=float, default=20.0)
    ap.add_argument("--out", default=None)
    ap.add_argument("cmd", nargs=argparse.REMAINDER)
    a = ap.parse_args()

    cmd = a.cmd
    if cmd and cmd[0] == "--":
        cmd = cmd[1:]

    pid, fd = pty.fork()
    if pid == 0:
        os.environ["TERM"] = os.environ.get("FAKETERM", "xterm-256color")
        os.environ["COLUMNS"] = str(a.cols)
        os.environ["LINES"] = str(a.rows)
        try:
            os.execvp(cmd[0], cmd)
        except Exception as e:
            sys.stderr.write(str(e)); os._exit(127)

    set_size(fd, a.rows, a.cols)
    buf = bytearray()
    dead = [False]

    def pump(t):
        end = time.time() + t
        while True:
            rem = end - time.time()
            if rem <= 0: break
            r, _, _ = select.select([fd], [], [], rem)
            if r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    dead[0] = True; return False
                if not d:
                    dead[0] = True; return False
                buf.extend(d)
        return True

    alive = pump(a.initial_wait)
    for k in parse_keys(a.keys):
        if not alive: break
        if isinstance(k, tuple):
            pump(k[1]); continue
        try:
            os.write(fd, k.encode())
        except OSError:
            break
        alive = pump(a.delay)

    # wait for exit
    t0 = time.time()
    status = None
    while time.time() - t0 < a.exit_wait:
        pump(0.2)
        try:
            wpid, st = os.waitpid(pid, os.WNOHANG)
        except ChildProcessError:
            status = "reaped"; break
        if wpid == pid:
            status = st; break
    timedout = status is None
    if timedout:
        try: os.kill(pid, signal.SIGKILL)
        except Exception: pass
        try: os.waitpid(pid, 0)
        except Exception: pass
    data = bytes(buf)
    if a.out:
        open(a.out, "wb").write(data)
    if isinstance(status, int):
        if os.WIFEXITED(status):
            sys.stderr.write("EXITCODE=%d\n" % os.WEXITSTATUS(status))
        else:
            sys.stderr.write("SIGNAL=%d\n" % os.WTERMSIG(status))
    else:
        sys.stderr.write("TIMEOUT_KILLED\n")

main()
